#!/usr/bin/env bash
set -euo pipefail

HEX=''
PATTERN="$(python - <<'PY'
import binascii
print(binascii.unhexlify('').decode())
PY
)"

if rg -nI --hidden \
  -g '!node_modules/**' \
  -g '!.git/**' \
  -g '!dist/**' \
  -g '!build/**' \
  -g '!coverage/**' \
  -g '!scripts/no_crypto_guard.sh' \
  -e "$PATTERN" .; then
  echo "[guard] forbidden terms detected"
  exit 1
fi

echo "[guard] ok"
